import React from "react"
import { Link } from "react-router-dom"
import QuestionMark from "../assets/images/notfound-image.png"

export default function NotFound() {
    return (
        <div className="notfound--container">
            <img
                className="notfound--image"
                src={QuestionMark}
            />
            <h1 className="notfound--text white">Sorry, the page you were looking for was not found.</h1>
            <Link to="/" className="site--link1">Go to homepage</Link>
        </div>
    )
}
