import { signal } from "@preact/signals-react"
import api from "./functions.json"
import tags from "./tags.json"
import { sanitizeString } from "./utils";

function createAppState() {
    const apiPages = signal(api); //JSON containing all pages
    const tagTypes = signal(tags); //JSON containing assigned tag categories
    const selectedTags = signal([]); //The selected tags for filtering
    const searchQuery = signal(""); //Current search query
    const searchTimeout = signal(null); 
    const searchFocus = signal(false);
    const tdPatch = signal(164); //Current Teardown patch
    const apiPage = signal("script"); //Selected API page

    function updateSearch(event) {
        const value = event.target.value
        const delay = 500 //milliseconds

        if (searchTimeout.value) {
            clearTimeout(searchTimeout.value)
        }

        const newTimeoutId = setTimeout(() => {
            //console.log(`Set searchQuery to "${value}"`)
            const sanitizedValue = sanitizeString(value)
            searchQuery.value = sanitizedValue
            event.target.value = sanitizedValue
        }, delay)

        searchTimeout.value = newTimeoutId
    }

    function updateQuery(query) {
        const inputs = Array.from(document.getElementsByClassName("search--input"));
        const sanitizedQuery = sanitizeString(query);

        searchQuery.value = sanitizedQuery;

        inputs.forEach(input => {
            input.value = sanitizedQuery;
        })
    }

    function updateTags(tag) {
        const index = selectedTags.value.indexOf(tag)
        if (index > -1) {
            //console.log(`Removed tag ${tag}`)
            // if the tag already exists, filter it out of the selected tags
            selectedTags.value = selectedTags.value.filter(selected => selected !== tag);
        } else {
            //console.log(`Added tag ${tag}`)
            // if the tag doesn't exist, add it to the selected tags
            selectedTags.value = [ ...selectedTags.value, tag ]
        }
    }

    return {
        apiPages,
        tagTypes,
        selectedTags,
        searchQuery,
        searchFocus,
        tdPatch,
        apiPage,
        updateTags,
        updateSearch,
        updateQuery
    };
};

export default createAppState;